import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart'; import 'package:go_router/go_router.dart';
import '../../state/providers.dart'; import '../../widgets/app_scaffold.dart'; import '../tree/widgets/member_avatar.dart';
class MemberProfileScreen extends ConsumerStatefulWidget{ const MemberProfileScreen({super.key,required this.familyId,required this.memberId}); final String familyId,memberId; @override ConsumerState<MemberProfileScreen> createState()=>_S();} class _S extends ConsumerState<MemberProfileScreen>{ final revealed=<String>{}; @override Widget build(BuildContext context){ final fam=ref.watch(familyProvider(widget.familyId)).valueOrNull; final members=ref.watch(membersProvider(widget.familyId)).valueOrNull??[]; final m=members.where((x)=>x.id==widget.memberId).firstOrNull; final schema=fam==null?null:ref.watch(schemaProvider(fam.fieldSchemaId)).valueOrNull; if(fam==null||m==null)return const Scaffold(body:Center(child:CircularProgressIndicator())); return AppScaffold(title:'${m.data['firstName']} ${m.data['lastName']??''}', familyId:widget.familyId, actions:[IconButton(onPressed:()=>context.go('/family/${widget.familyId}/member/${m.id}/edit'), icon:const Icon(Icons.edit))], child:ListView(padding:const EdgeInsets.all(16), children:[Center(child:InkWell(onTap:()=>context.go('/photo?url=${Uri.encodeComponent((m.data['photo']??'').toString())}'), child:MemberAvatar(member:m,settings:fam.settings,size:160))), for(final f in schema?.fields??[]) if(f.key!='photo' && (m.data[f.key]?.toString().isNotEmpty??false)) Card(child:ListTile(leading:Icon(f.sensitive?Icons.lock:Icons.label), title:Text(f.label), subtitle:f.sensitive&&!revealed.contains(f.key)?const Text('Tap to reveal sensitive field'):Text('${m.data[f.key]}'), onTap:f.sensitive?()=>setState(()=>revealed.add(f.key)):null))]));}}
extension FirstOrNull<E> on Iterable<E>{E? get firstOrNull=>isEmpty?null:first;}
